// Preparing a CKShare

func createShare(contactRecord: CKRecord) async throws -> CKShare {
    let share = CKShare(rootRecord: contactRecord)

    try await privateCloudDatabase.modifyRecords(
        saving: [contactRecord, share], 
        deleting: []
    )

    return share
}

